    [InitializeOnLoad]public static class HitWeaponAuthoring
    {
        public const string Art="Assets/IronRequiem/Art/CombatIntegrationV04",Lab="Assets/IronRequiem/Scenes/HitWeaponLab.unity",Big="Assets/IronRequiem/Prefabs/Enemies/BigBot_HitFeedback_v04.prefab",T07="Assets/IronRequiem/Prefabs/Enemies/T07_HitFeedback_v04.prefab",Player="Assets/IronRequiem/Prefabs/Player/Player_Integrated_v04.prefab",Weapon="Assets/IronRequiem/Prefabs/Weapons/Weapon_IR_Integrated_v04.prefab",Reports="Tools/IronRequiem/Reports/HitWeaponV04",Working="Tools/IronRequiem/Blender/Working/HitWeaponV04";
        const string Queue="Tools/IronRequiem/Requests/hit-weapon.txt",Key="IRON.HitWeapon";static readonly DateTime LoadedAt=DateTime.UtcNow;static TestRunnerApi api;
        static HitWeaponAuthoring(){EditorApplication.update+=Tick;if(SessionState.GetBool(Key+".testing",false))EditorApplication.delayCall+=Register;}
        static bool Dirty()=>Enumerable.Range(0,SceneManager.sceneCount).Any(i=>SceneManager.GetSceneAt(i).isDirty);
        static void Register(){if(!api){api=ScriptableObject.CreateInstance<TestRunnerApi>();api.RegisterCallbacks(new Results());}}
        static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||SessionState.GetBool(Key+".testing",false))return;if(SessionState.GetBool(Key+".restore",false)&&EditorApplication.timeSinceStartup-SessionState.GetFloat(Key+".at",0)>3){SessionState.EraseBool(Key+".restore");if(!Dirty())EditorSceneManager.OpenScene(Lab);}if(!File.Exists(Queue))return;foreach(var path in new[]{"Assets/IronRequiem/Editor/HitWeaponAuthoring.cs","Assets/IronRequiem/Tests/PlayMode/RobotImpactFeedbackTests.cs","Assets/IronRequiem/Tests/PlayMode/PrimaryModuleTests.cs","Assets/IronRequiem/Scripts/Enemies/RobotHitFeedback.cs"})if(File.Exists(path)&&LoadedAt<File.GetLastWriteTimeUtc(path))return;var op=File.ReadAllText(Queue).Trim();File.Delete(Queue);Directory.CreateDirectory(Reports);Directory.CreateDirectory(Working);try{if(op=="feedback"){BuildFeedback();InspectTemplate();File.WriteAllText(Queue,"test-feedback");}else if(op=="test-feedback")Run("feedback",new[]{"IronRequiem.Tests.RobotImpactFeedbackTests.BulletAndMeleeUnique","IronRequiem.Tests.RobotImpactFeedbackTests.RestoreStageAndRepeatedHits","IronRequiem.Tests.RobotImpactFeedbackTests.AttacksContinueAndDeathClears"});else if(op=="weapon"){BuildWeapon();File.WriteAllText(Queue,"test-final");}else if(op=="test-weapon")Run("weapon",new[]{"IronRequiem.Tests.PrimaryModuleTests.IntegratedMount","IronRequiem.Tests.RobotImpactFeedbackTests.ModuleSwap"});else if(op=="patch-feedback"){foreach(var path in new[]{Big,T07}){var go=PrefabUtility.LoadPrefabContents(path);try{go.GetComponentInChildren<DetectionModule>(true).UseExternalDamagePresentation=true;PrefabUtility.SaveAsPrefabAsset(go,path);}finally{PrefabUtility.UnloadPrefabContents(go);}}AssetDatabase.SaveAssets();File.WriteAllText(Queue,"test-feedback");}else if(op=="test-final")Run("final",new[]{"IronRequiem.Tests.RobotImpactFeedbackTests.AttacksContinueAndDeathClears","IronRequiem.Tests.PrimaryModuleTests.IntegratedMount","IronRequiem.Tests.RobotImpactFeedbackTests.ModuleSwap"});else if(op=="polish"){var body=AssetDatabase.LoadAssetAtPath<Material>(Art+"/Weapon_PlayerSurface.mat");body.SetFloat("_BumpScale",0);EditorUtility.SetDirty(body);var glass=AssetDatabase.LoadAssetAtPath<Material>(Art+"/Weapon_PlayerCyanEnergy.mat");glass.SetColor("_EmissionColor",new Color(.0868f,.4873f,.5433f)*.2f);EditorUtility.SetDirty(glass);AssetDatabase.ImportAsset(Art+"/IR_TemplateArmModule_v04.fbx",ImportAssetOptions.ForceSynchronousImport|ImportAssetOptions.ForceUpdate);AssetDatabase.SaveAssets();Run("visual",new[]{"IronRequiem.Tests.PrimaryModuleTests.IntegratedMount"});}else if(op=="verify")Verify();else throw new InvalidOperationException("Unknown fixed operation");}catch(Exception e){File.WriteAllText(Reports+"/error.txt",e.ToString());Debug.LogException(e);}}
        static void Run(string label,string[] names){if(Dirty())throw new InvalidOperationException("Preserving dirty user scene");Register();SessionState.SetString(Key+".label",label);SessionState.SetBool(Key+".testing",true);api.Execute(new ExecutionSettings(new Filter{testMode=TestMode.PlayMode,testNames=names}));}
        static void Variant(string source,string dest){if(File.Exists(dest))throw new InvalidOperationException("Preserve existing "+dest);var scene=EditorSceneManager.NewPreviewScene();try{var go=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(source),scene);go.name=Path.GetFileNameWithoutExtension(dest);PrefabUtility.SaveAsPrefabAsset(go,dest);}finally{EditorSceneManager.ClosePreviewScene(scene);}}
        static Material FeedbackMaterial(Material source,Dictionary<Material,Material> copies){if(!source)return null;if(copies.TryGetValue(source,out var found))return found;string path=Art+"/Hit_"+source.name+"_"+AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(source)).Substring(0,6)+".mat";if(!File.Exists(path))AssetDatabase.CopyAsset(AssetDatabase.GetAssetPath(source),path);var copy=AssetDatabase.LoadAssetAtPath<Material>(path);if(copy.HasProperty("_EmissionColor")){if(copy.GetColor("_EmissionColor").maxColorComponent<.001f)copy.SetColor("_EmissionColor",new Color(.0001f,.0001f,.0001f));copy.globalIlluminationFlags=MaterialGlobalIlluminationFlags.BakedEmissive;copy.EnableKeyword("_EMISSION");}EditorUtility.SetDirty(copy);copies[source]=copy;return copy;}
        static void BuildFeedback(){if(Dirty())throw new InvalidOperationException("Preserving dirty scene");Directory.CreateDirectory(Art);AssetDatabase.Refresh();Variant(CombatPolishAuthoring.Enemy,Big);Variant(CombatPolishAuthoring.Types[1],T07);Variant(PrimaryCapsulesAuthoring.Player,Player);var original=PrefabUtility.LoadPrefabContents("Assets/FPS/Prefabs/Enemies/Enemy_HoverBot.prefab");try{var reference=original.GetComponent<EnemyController>();var sourceSparks=original.GetComponent<EnemyMobile>().RandomHitSparks[0];var copies=new Dictionary<Material,Material>();foreach(var path in new[]{Big,T07}){var go=PrefabUtility.LoadPrefabContents(path);try{var views=go.GetComponentsInChildren<Renderer>(true).Where(r=>!(r is ParticleSystemRenderer)&&r.enabled&&r.gameObject.activeInHierarchy&&r.name!="PowerIndicator"&&r.name!="JointIndicator").ToArray();foreach(var r in views)r.sharedMaterials=r.sharedMaterials.Select(m=>FeedbackMaterial(m,copies)).ToArray();foreach(var component in go.GetComponents<MonoBehaviour>().Where(c=>c is BigBotDestruction||c is RobotDamageProgression)){var data=new SerializedObject(component);var prop=data.GetIterator();while(prop.NextVisible(true))if(prop.propertyType==SerializedPropertyType.ObjectReference&&prop.objectReferenceValue is Material material)prop.objectReferenceValue=FeedbackMaterial(material,copies);data.ApplyModifiedPropertiesWithoutUndo();}
                    var mobile=go.GetComponent<EnemyMobile>();mobile.UseExternalDamagePresentation=true;go.GetComponentInChildren<DetectionModule>(true).UseExternalDamagePresentation=true;mobile.RandomHitSparks=Array.Empty<ParticleSystem>();go.GetComponent<EnemyController>().BodyMaterial=null;
                    var sparkGo=Object.Instantiate(sourceSparks.gameObject,go.transform);sparkGo.name="RobotLocalizedHitSparks";sparkGo.transform.localScale=Vector3.one/go.transform.lossyScale.x;var ps=sparkGo.GetComponent<ParticleSystem>();foreach(var child in sparkGo.GetComponentsInChildren<ParticleSystem>(true)){child.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=child.main;main.loop=false;main.duration=.45f;main.playOnAwake=false;main.stopAction=ParticleSystemStopAction.None;main.simulationSpace=ParticleSystemSimulationSpace.World;main.scalingMode=ParticleSystemScalingMode.Shape;main.maxParticles=path==Big?48:32;main.startLifetime=new ParticleSystem.MinMaxCurve(.16f,.28f);main.startSpeed=new ParticleSystem.MinMaxCurve(1.5f,3);main.startSize=new ParticleSystem.MinMaxCurve(.022f,.045f);var emission=child.emission;emission.rateOverTime=0;emission.rateOverDistance=0;emission.SetBursts(Array.Empty<ParticleSystem.Burst>());var lights=child.lights;lights.enabled=false;var sub=child.subEmitters;sub.enabled=false;child.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);}
                    var skin=go.GetComponentsInChildren<SkinnedMeshRenderer>(true).First(r=>r.name==(path==Big?"Torso_LOD0":"Body_LOD0"));var joint=skin.bones.Single(b=>b.name==(path==Big?"Torso":"Chest"));go.AddComponent<RobotHitFeedback>().Configure(views,joint,ps,reference.OnHitBodyGradient);PrefabUtility.SaveAsPrefabAsset(go,path);
                }finally{PrefabUtility.UnloadPrefabContents(go);}}File.WriteAllText(Reports+"/template.txt","HoverBot: EnemyController emission gradient; EnemyMobile local sparks and OnDamaged Animator trigger. Adapted with short white emission pulse and additive torso rotation; native attack triggers bypassed only on feedback variants.");}finally{PrefabUtility.UnloadPrefabContents(original);}
            if(File.Exists(Lab))throw new InvalidOperationException("Preserve existing lab");AssetDatabase.CopyAsset(PrimaryCapsulesAuthoring.Lab,Lab);var scene=EditorSceneManager.OpenScene(Lab);foreach(var source in new[]{(typeof(BigBotCombat),Big),(typeof(RobotDamageProgression),T07),(typeof(PlayerCharacterController),Player)}){var old=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren(source.Item1,true)).Single().gameObject;var go=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(source.Item2),scene);go.transform.SetPositionAndRotation(old.transform.position,old.transform.rotation);go.transform.localScale=old.transform.localScale;foreach(var route in Object.FindObjectsByType<PatrolPath>())for(int i=0;i<route.EnemiesToAssign.Count;i++)if(route.EnemiesToAssign[i]==old.GetComponent<EnemyController>())route.EnemiesToAssign[i]=go.GetComponent<EnemyController>();Object.DestroyImmediate(old);}var surface=Object.FindAnyObjectByType<Unity.AI.Navigation.NavMeshSurface>();surface.RemoveData();surface.navMeshData=AssetDatabase.LoadAssetAtPath<UnityEngine.AI.NavMeshData>(PrimaryModuleAuthoring.Art+"/PrimaryModule_NavMesh.asset");surface.AddData();EditorUtility.SetDirty(surface);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();}
        [Serializable]sealed class Geometry{public Part[] parts;public string playerMaterial;}
        [Serializable]sealed class Part{public string name;public Vector3[] vertices;public int[] triangles;}
        static void InspectTemplate(){var go=PrefabUtility.LoadPrefabContents("Assets/FPS/Prefabs/Weapons/Weapon_Blaster.prefab");try{var parts=go.GetComponentsInChildren<MeshFilter>(true).Where(m=>m.name=="Primary_Weapon"||m.name.StartsWith("Primary_Weapon_Front_Piece")).Select(m=>new Part{name=m.name,vertices=m.sharedMesh.vertices.Select(v=>go.transform.InverseTransformPoint(m.transform.TransformPoint(v))).ToArray(),triangles=m.sharedMesh.triangles}).ToArray();File.WriteAllText(Working+"/template-geometry.json",JsonUtility.ToJson(new Geometry{parts=parts,playerMaterial="Assets/IronRequiem/Art/Player/ProtagonistV01/Materials/IR_Protagonist_URP.mat"},true));}finally{PrefabUtility.UnloadPrefabContents(go);}}
        [Serializable]sealed class Region{public float x,y,width,height;public float[] rgb;}
        [Serializable]sealed class Regions{public Region armor,metal,orange,cyan;}
        [Serializable]sealed class WeaponReport{public Regions uv_regions;}
        static void BuildWeapon()
        {
            if(Dirty())throw new InvalidOperationException("Preserving dirty user scene");string model=Art+"/IR_TemplateArmModule_v04.fbx";if(!File.Exists(model))File.Copy(Working+"/IR_TemplateArmModule_v04.fbx",model);AssetDatabase.ImportAsset(model,ImportAssetOptions.ForceSynchronousImport);var importer=(ModelImporter)AssetImporter.GetAtPath(model);importer.materialImportMode=ModelImporterMaterialImportMode.None;importer.animationType=ModelImporterAnimationType.None;importer.importAnimation=false;importer.SaveAndReimport();
            string bodyPath=Art+"/Weapon_PlayerSurface.mat";if(!File.Exists(bodyPath))AssetDatabase.CopyAsset("Assets/IronRequiem/Art/Player/ProtagonistV01/Materials/IR_Protagonist_URP.mat",bodyPath);var material=AssetDatabase.LoadAssetAtPath<Material>(bodyPath);var regions=JsonUtility.FromJson<WeaponReport>(File.ReadAllText(Working+"/weapon-geometry.json")).uv_regions;
            if(!File.Exists(Weapon))Variant(PrimaryCapsulesAuthoring.Weapon,Weapon);var go=PrefabUtility.LoadPrefabContents(Weapon);try{var weapon=go.GetComponent<WeaponController>();var previous=go.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="PrimaryModuleVisual");previous.name="Preserved_Module_v03";previous.gameObject.SetActive(false);foreach(var t in previous.GetComponentsInChildren<Transform>(true)){if(t.name=="Attachment")t.name="Preserved_Attachment_v03";if(t.name=="Muzzle")t.name="Preserved_Muzzle_v03";}
                var visual=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(model),go.scene);visual.name="PrimaryModuleVisual";visual.transform.SetParent(weapon.WeaponRoot.transform,false);var muzzle=visual.GetComponentsInChildren<Transform>().Single(t=>t.name=="Muzzle");visual.transform.position+=weapon.WeaponMuzzle.position-muzzle.position;muzzle.rotation=weapon.WeaponMuzzle.rotation;visual.GetComponentsInChildren<Transform>().Single(t=>t.name=="Attachment").rotation=weapon.WeaponMuzzle.rotation;foreach(var r in visual.GetComponentsInChildren<Renderer>())r.sharedMaterial=material;
                var cells=go.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="TemplateCapsules");int n=0;Material glass=null;foreach(var filter in cells.GetComponentsInChildren<MeshFilter>()){
                    var renderer=filter.GetComponent<MeshRenderer>();var source=renderer.sharedMaterials;if(!glass){string path=Art+"/Weapon_PlayerCyanEnergy.mat";if(!File.Exists(path))AssetDatabase.CopyAsset(AssetDatabase.GetAssetPath(source.Last()),path);glass=AssetDatabase.LoadAssetAtPath<Material>(path);var cyan=new Color(regions.cyan.rgb[0],regions.cyan.rgb[1],regions.cyan.rgb[2],glass.GetColor("_BaseColor").a);glass.SetTexture("_BaseMap",null);glass.SetTexture("_EmissionMap",null);glass.SetColor("_BaseColor",cyan);float energy=Mathf.Max(.6f,glass.GetColor("_EmissionColor").maxColorComponent);glass.SetColor("_EmissionColor",new Color(cyan.r,cyan.g,cyan.b)*energy/Mathf.Max(.001f,cyan.maxColorComponent));glass.globalIlluminationFlags=MaterialGlobalIlluminationFlags.BakedEmissive;glass.EnableKeyword("_EMISSION");EditorUtility.SetDirty(glass);}
                    string meshPath=Art+"/Capsule_PlayerUV_"+(++n)+".asset";if(!File.Exists(meshPath)){var mesh=Object.Instantiate(filter.sharedMesh);mesh.name="Capsule_PlayerUV_"+n;var uv=mesh.uv;foreach(int i in mesh.GetTriangles(0).Distinct())uv[i]=new Vector2(regions.metal.x+regions.metal.width*(.03f+.94f*Mathf.Repeat(uv[i].x,1)),regions.metal.y+regions.metal.height*(.03f+.94f*Mathf.Repeat(uv[i].y,1)));mesh.uv=uv;AssetDatabase.CreateAsset(mesh,meshPath);}filter.sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>(meshPath);renderer.sharedMaterials=source.Select((m,i)=>i==0?material:glass).ToArray();
                }PrefabUtility.SaveAsPrefabAsset(go,Weapon);
            }finally{PrefabUtility.UnloadPrefabContents(go);}
            go=PrefabUtility.LoadPrefabContents(Player);try{var manager=go.GetComponent<PlayerWeaponsManager>();var weapon=AssetDatabase.LoadAssetAtPath<GameObject>(Weapon).GetComponent<WeaponController>();for(int i=0;i<manager.StartingWeapons.Count;i++)if(manager.StartingWeapons[i].name=="Weapon_IR_PrimaryCapsules_v03")manager.StartingWeapons[i]=weapon;var hands=new SerializedObject(go.GetComponent<ProtagonistHandsPresentation>());hands.FindProperty("pistolPrefab").objectReferenceValue=weapon;hands.ApplyModifiedPropertiesWithoutUndo();PrefabUtility.SaveAsPrefabAsset(go,Player);}finally{PrefabUtility.UnloadPrefabContents(go);}AssetDatabase.SaveAssets();
        }
        static void Verify(){IronRequiemSetupTools.WriteAudit();}
        sealed class Results:IErrorCallbacks{public void RunStarted(ITestAdaptor t){}public void TestStarted(ITestAdaptor t){}public void TestFinished(ITestResultAdaptor t){}public void OnError(string message){SessionState.EraseBool(Key+".testing");File.WriteAllText(Reports+"/runner-error.txt",message);}public void RunFinished(ITestResultAdaptor result){if(!SessionState.GetBool(Key+".testing",false))return;SessionState.EraseBool(Key+".testing");string label=SessionState.GetString(Key+".label","");TestRunnerApi.SaveResultToFile(result,Reports+"/"+label+".xml");File.WriteAllText(Reports+"/status.txt",label+": "+result.ResultState+" passed="+result.PassCount+" failed="+result.FailCount);SessionState.SetBool(Key+".restore",true);SessionState.SetFloat(Key+".at",(float)EditorApplication.timeSinceStartup);}}
    }
